SELECT id, child_id, report_type_id, report_year, report_month,
       total_spent, transaction_count, top_spots, total_saved,
       allowance_received, saving_rate, advice
FROM child_spending_reports
WHERE child_id = #{childId}
  AND report_year = #{year}
  AND report_month = #{month}

SELECT COUNT(*)
FROM child_spending_reports
WHERE report_type_id = #{reportTypeId}
  AND report_year = #{year}
  AND report_month = #{month}

SELECT COUNT(*)
FROM child_spending_reports
WHERE report_year = #{year}
  AND report_month = #{month}
